import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const SimpleDashboard = () => {
  const navigate = useNavigate();
  const [companyData, setCompanyData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const loadData = async () => {
      try {
        console.log('Dashboard: Loading data from localStorage...');
        const storedCompanyData = localStorage.getItem('companyData');
        console.log('Dashboard: Raw stored data:', storedCompanyData);

        if (!storedCompanyData) {
          console.log('Dashboard: No company data found, redirecting...');
          navigate('/');
          return;
        }

        const companyData = JSON.parse(storedCompanyData);
        console.log('Dashboard: Parsed company data:', companyData);
        setCompanyData(companyData);
      } catch (err) {
        console.error('Dashboard: Error loading data:', err);
        setError('Failed to load dashboard data: ' + err.message);
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, [navigate]);

  const formatCurrency = (amount) => {
    if (!amount) return '₹0';
    if (amount >= 10000000) {
      return `₹${(amount / 10000000).toFixed(1)}Cr`;
    } else if (amount >= 100000) {
      return `₹${(amount / 100000).toFixed(1)}L`;
    } else {
      return `₹${amount.toLocaleString('en-IN')}`;
    }
  };

  if (loading) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: '#f0f9ff' }}>
        <div style={{ textAlign: 'center' }}>
          <div style={{ 
            width: '48px', 
            height: '48px', 
            border: '4px solid #e5e7eb', 
            borderTop: '4px solid #2563eb', 
            borderRadius: '50%', 
            animation: 'spin 1s linear infinite',
            margin: '0 auto 16px'
          }}></div>
          <p style={{ fontSize: '18px', color: '#4b5563' }}>Loading your credit analysis...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: '#f0f9ff' }}>
        <div style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '48px', marginBottom: '16px' }}>⚠️</div>
          <h2 style={{ fontSize: '24px', fontWeight: 'bold', color: '#dc2626', marginBottom: '8px' }}>Error Loading Dashboard</h2>
          <p style={{ color: '#6b7280', marginBottom: '24px' }}>{error}</p>
          <button 
            onClick={() => window.location.reload()}
            style={{ 
              backgroundColor: '#2563eb', 
              color: 'white', 
              padding: '12px 24px', 
              borderRadius: '8px',
              border: 'none',
              cursor: 'pointer'
            }}
          >
            Try Again
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#f0f9ff' }}>
      {/* Header */}
      <div style={{ 
        background: 'linear-gradient(to right, #2563eb, #4f46e5)', 
        color: 'white', 
        padding: '32px 0',
        boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)'
      }}>
        <div style={{ maxWidth: '1280px', margin: '0 auto', padding: '0 16px' }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <div>
              <h1 style={{ fontSize: '36px', fontWeight: 'bold', marginBottom: '8px', display: 'flex', alignItems: 'center' }}>
                <span style={{ marginRight: '12px' }}>🏦</span>
                AI Credit Analysis Dashboard
              </h1>
              <p style={{ fontSize: '20px', color: '#dbeafe' }}>
                {companyData?.company || 'Company'} - Comprehensive Risk Assessment
              </p>
              <div style={{ marginTop: '8px', display: 'flex', alignItems: 'center', gap: '16px' }}>
                <span style={{ backgroundColor: 'rgba(255, 255, 255, 0.2)', padding: '4px 12px', borderRadius: '9999px', fontSize: '14px' }}>
                  📊 Dynamic Analysis
                </span>
                <span style={{ backgroundColor: 'rgba(255, 255, 255, 0.2)', padding: '4px 12px', borderRadius: '9999px', fontSize: '14px' }}>
                  🤖 AI-Powered
                </span>
                <span style={{ backgroundColor: 'rgba(255, 255, 255, 0.2)', padding: '4px 12px', borderRadius: '9999px', fontSize: '14px' }}>
                  ⚡ Real-time
                </span>
              </div>
            </div>
            <div style={{ display: 'flex', gap: '12px' }}>
              <button
                onClick={() => navigate('/research')}
                style={{ 
                  backgroundColor: 'white', 
                  color: '#2563eb', 
                  padding: '12px 24px', 
                  borderRadius: '8px',
                  border: 'none',
                  cursor: 'pointer',
                  fontWeight: '600',
                  boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)'
                }}
              >
                📈 Research Insights
              </button>
              <button
                onClick={() => navigate('/cam-preview')}
                style={{ 
                  backgroundColor: '#10b981', 
                  color: 'white', 
                  padding: '12px 24px', 
                  borderRadius: '8px',
                  border: 'none',
                  cursor: 'pointer',
                  fontWeight: '600',
                  boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)'
                }}
              >
                📄 Generate CAM
              </button>
            </div>
          </div>
        </div>
      </div>

      <div style={{ maxWidth: '1280px', margin: '0 auto', padding: '32px 16px' }}>
        {/* Key Metrics */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '24px', marginBottom: '32px' }}>
          <div style={{ 
            backgroundColor: 'white', 
            padding: '24px', 
            borderRadius: '12px', 
            textAlign: 'center',
            boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
            border: '1px solid #e5e7eb'
          }}>
            <div style={{ fontSize: '48px', marginBottom: '16px' }}>🛡️</div>
            <h3 style={{ fontSize: '18px', fontWeight: '600', color: '#111827', marginBottom: '4px' }}>Risk Score</h3>
            <div style={{ fontSize: '32px', fontWeight: 'bold', color: '#2563eb' }}>
              {companyData?.ai_analysis?.risk_analysis?.risk_score || 0}
              <span style={{ fontSize: '18px', color: '#6b7280' }}>/100</span>
            </div>
            <div style={{ marginTop: '8px', fontSize: '14px', color: '#6b7280' }}>
              AI-Calculated Risk Assessment
            </div>
          </div>

          <div style={{ 
            backgroundColor: 'white', 
            padding: '24px', 
            borderRadius: '12px', 
            textAlign: 'center',
            boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
            border: '1px solid #e5e7eb'
          }}>
            <div style={{ fontSize: '48px', marginBottom: '16px' }}>✅</div>
            <h3 style={{ fontSize: '18px', fontWeight: '600', color: '#111827', marginBottom: '4px' }}>Decision</h3>
            <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#10b981' }}>
              {companyData?.ai_analysis?.decision_result?.decision || 'Pending'}
            </div>
            <div style={{ marginTop: '8px', fontSize: '14px', color: '#6b7280' }}>
              Intelligent Credit Decision
            </div>
          </div>

          <div style={{ 
            backgroundColor: 'white', 
            padding: '24px', 
            borderRadius: '12px', 
            textAlign: 'center',
            boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
            border: '1px solid #e5e7eb'
          }}>
            <div style={{ fontSize: '48px', marginBottom: '16px' }}>💰</div>
            <h3 style={{ fontSize: '18px', fontWeight: '600', color: '#111827', marginBottom: '4px' }}>Loan Limit</h3>
            <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#10b981' }}>
              {formatCurrency(companyData?.ai_analysis?.loan_analysis?.approved_loan_amount || 0)}
            </div>
            <div style={{ marginTop: '8px', fontSize: '14px', color: '#6b7280' }}>
              AI-Calculated Affordability
            </div>
          </div>

          <div style={{ 
            backgroundColor: 'white', 
            padding: '24px', 
            borderRadius: '12px', 
            textAlign: 'center',
            boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
            border: '1px solid #e5e7eb'
          }}>
            <div style={{ fontSize: '48px', marginBottom: '16px' }}>📈</div>
            <h3 style={{ fontSize: '18px', fontWeight: '600', color: '#111827', marginBottom: '4px' }}>Interest Rate</h3>
            <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#f59e0b' }}>
              {companyData?.ai_analysis?.loan_analysis?.interest_rate || 0}%
            </div>
            <div style={{ marginTop: '8px', fontSize: '14px', color: '#6b7280' }}>
              Risk-Based Pricing
            </div>
          </div>
        </div>

        {/* Financial Overview */}
        {companyData && (
          <div style={{ 
            backgroundColor: 'white', 
            padding: '32px', 
            borderRadius: '12px', 
            marginBottom: '32px',
            boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
            border: '1px solid #e5e7eb'
          }}>
            <h3 style={{ fontSize: '24px', fontWeight: 'bold', color: '#111827', marginBottom: '24px', display: 'flex', alignItems: 'center' }}>
              <span style={{ marginRight: '12px' }}>📊</span>
              Financial Overview
            </h3>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '24px' }}>
              <div style={{ 
                background: 'linear-gradient(to bottom right, #dbeafe, #bfdbfe)', 
                padding: '24px', 
                borderRadius: '12px', 
                border: '1px solid #93c5fd'
              }}>
                <p style={{ fontSize: '14px', color: '#1e40af', fontWeight: '600', marginBottom: '8px' }}>Revenue</p>
                <p style={{ fontSize: '24px', fontWeight: 'bold', color: '#1e40af' }}>
                  {formatCurrency(companyData.revenue || 0)}
                </p>
                <div style={{ marginTop: '8px', fontSize: '12px', color: '#1e40af' }}>Annual Revenue</div>
              </div>
              <div style={{ 
                background: 'linear-gradient(to bottom right, #d1fae5, #a7f3d0)', 
                padding: '24px', 
                borderRadius: '12px', 
                border: '1px solid #6ee7b7'
              }}>
                <p style={{ fontSize: '14px', color: '#065f46', fontWeight: '600', marginBottom: '8px' }}>Profit</p>
                <p style={{ fontSize: '24px', fontWeight: 'bold', color: '#065f46' }}>
                  {formatCurrency(companyData.profit || 0)}
                </p>
                <div style={{ marginTop: '8px', fontSize: '12px', color: '#065f46' }}>Net Profit</div>
              </div>
              <div style={{ 
                background: 'linear-gradient(to bottom right, #f3e8ff, #e9d5ff)', 
                padding: '24px', 
                borderRadius: '12px', 
                border: '1px solid #d8b4fe'
              }}>
                <p style={{ fontSize: '14px', color: '#6b21a8', fontWeight: '600', marginBottom: '8px' }}>Assets</p>
                <p style={{ fontSize: '24px', fontWeight: 'bold', color: '#6b21a8' }}>
                  {formatCurrency(companyData.assets || 0)}
                </p>
                <div style={{ marginTop: '8px', fontSize: '12px', color: '#6b21a8' }}>Total Assets</div>
              </div>
              <div style={{ 
                background: 'linear-gradient(to bottom right, #fed7aa, #fdba74)', 
                padding: '24px', 
                borderRadius: '12px', 
                border: '1px solid #fb923c'
              }}>
                <p style={{ fontSize: '14px', color: '#9a3412', fontWeight: '600', marginBottom: '8px' }}>Liabilities</p>
                <p style={{ fontSize: '24px', fontWeight: 'bold', color: '#9a3412' }}>
                  {formatCurrency(companyData.liabilities || 0)}
                </p>
                <div style={{ marginTop: '8px', fontSize: '12px', color: '#9a3412' }}>Total Liabilities</div>
              </div>
            </div>
          </div>
        )}

        {/* Debug Information */}
        <div style={{ 
          backgroundColor: 'white', 
          padding: '32px', 
          borderRadius: '12px',
          boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
          border: '1px solid #e5e7eb'
        }}>
          <h3 style={{ fontSize: '24px', fontWeight: 'bold', color: '#111827', marginBottom: '24px', display: 'flex', alignItems: 'center' }}>
            <span style={{ marginRight: '12px' }}>🔍</span>
            Debug Information
          </h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            <div style={{ backgroundColor: '#f9fafb', padding: '16px', borderRadius: '8px' }}>
              <p style={{ fontSize: '14px', fontWeight: '600', color: '#374151' }}>Loading Status: {loading.toString()}</p>
              <p style={{ fontSize: '14px', fontWeight: '600', color: '#374151' }}>Error: {error || 'None'}</p>
              <p style={{ fontSize: '14px', fontWeight: '600', color: '#374151' }}>Company Data: {companyData ? 'Loaded' : 'Not Loaded'}</p>
              <p style={{ fontSize: '14px', fontWeight: '600', color: '#374151' }}>AI Analysis: {companyData?.ai_analysis ? 'Available' : 'Not Available'}</p>
            </div>
            {companyData && (
              <div style={{ backgroundColor: '#dbeafe', padding: '16px', borderRadius: '8px' }}>
                <p style={{ fontSize: '14px', fontWeight: '600', color: '#1e40af' }}>Company: {companyData.company}</p>
                <p style={{ fontSize: '14px', fontWeight: '600', color: '#1e40af' }}>Revenue: {formatCurrency(companyData.revenue)}</p>
                <p style={{ fontSize: '14px', fontWeight: '600', color: '#1e40af' }}>Risk Score: {companyData.ai_analysis?.risk_analysis?.risk_score || 'N/A'}</p>
                <p style={{ fontSize: '14px', fontWeight: '600', color: '#1e40af' }}>Decision: {companyData.ai_analysis?.decision_result?.decision || 'N/A'}</p>
              </div>
            )}
          </div>
        </div>
      </div>

      <style jsx>{`
        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
};

export default SimpleDashboard;
